actions.script:
const out = ec.service.sync().name('ironstone.KnowledgeServices.get#KnowledgeSetup').parameter('wikiSpaceId', wikiSpaceId || null).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {spaceList: out.spaceList, defaultWikiSpaceId: out.defaultWikiSpaceId,
    recentList: out.recentList, reviewCount: out.reviewCount, me: out.me, failedParts: out.failedParts})

const out = ec.service.sync().name('ironstone.KnowledgeServices.get#PageChildren').parameters({wikiSpaceId: wikiSpaceId || '',
    pagePath: pagePath || ''}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {childList: out.childList})

const out = ec.service.sync().name('ironstone.KnowledgeServices.get#PageView').parameters({wikiPageId: wikiPageId || null,
    wikiSpaceId: wikiSpaceId || null, pagePath: pagePath || '', versionName: versionName || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {page: out.page, failedParts: out.failedParts})

const out = ec.service.sync().name('ironstone.KnowledgeServices.search#Pages').parameters({text: text || '', wikiSpaceId: wikiSpaceId || null,
    scope: 'knowledge'}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {pageList: out.pageList, usedIndex: out.usedIndex})

const out = ec.service.sync().name('ironstone.KnowledgeServices.get#SpacePageOptions').parameters({wikiSpaceId: wikiSpaceId || '',
    excludePagePath: excludePagePath || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {optionList: out.optionList, canUpdate: out.canUpdate})

const out = ec.service.sync().name('ironstone.KnowledgeServices.get#Attachment').parameters({wikiPageId: wikiPageId || '',
    filename: filename || ''}).call()
if (ec.message.hasError()) ec.web.sendJsonResponse({})
else ec.web.sendResourceResponse(out.location, String(inline) === 'true' && out.inlineAllowed)

const out = ec.service.sync().name('ironstone.KnowledgeServices.rename#Page').parameters({wikiPageId: wikiPageId || '', pageName: pageName || ''}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {wikiSpaceId: out.wikiSpaceId, pagePath: out.pagePath,
    messageInfos: [{type: 'success', message: ec.l10n.localize('Renamed')}]})

const out = ec.service.sync().name('ironstone.KnowledgeServices.drop#Page').parameters({wikiPageId: wikiPageId || '',
    targetPagePath: targetPagePath || '', position: position || 'inside'}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {wikiSpaceId: out.wikiSpaceId, pagePath: out.pagePath, oldPagePath: out.oldPagePath})

const out = ec.service.sync().name('ironstone.KnowledgeServices.delete#Page').parameter('wikiPageId', wikiPageId || '').call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {wikiSpaceId: out.wikiSpaceId, parentPath: out.parentPath,
    messageInfos: [{type: 'success', message: ec.l10n.localize('Page deleted')}]})

const out = ec.service.sync().name('ironstone.KnowledgeServices.cancel#Review').parameters({wikiPageReviewId: wikiPageReviewId || '',
    note: note || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {statusId: out.statusId, messageInfos: [{type: 'success', message: ec.l10n.localize('Review request cancelled')}]})

const out = ec.service.sync().name('ironstone.KnowledgeServices.set#PagePinned').parameters({wikiPageId: wikiPageId || '',
    pinned: String(pinned) === 'true'}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {pinned: out.pinned})

// the drop-down's value is entity|id
const value = String(record || '')
const bar = value.indexOf('|')
const entityName = bar > 0 ? value.substring(0, bar) : ''
const id = bar > 0 ? value.substring(bar + 1) : ''
ec.service.sync().name('ironstone.KnowledgeServices.link#PageRecord').parameters({wikiPageId: wikiPageId || '',
    recordEntityName: recordEntityName || entityName || '', recordId: recordId || id || ''}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {messageInfos: [{type: 'success', message: ec.l10n.localize('Linked')}]})
